=== stage-spec ===
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "planId",
  "producerClosure",
  "operation",
  "parameters",
  "outputDomains",
  "outputSchemaDigest"
 ],
 "description": "The closed record digested by stageSpecDigest. execution-plan.stages[].stageSpecDigest and cache-key.stageSpecDigest are the SAME field name because they are the same digest of the same record under the same recipe; there are not two recipes for one spelling.",
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "planId": {
   "type": "string",
   "pattern": "^plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "producerClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "operation": {
   "$ref": "#/$defs/Text"
  },
  "parameters": {
   "type": "array",
   "uniqueItems": true,
   "maxItems": 128,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "schemaDigest",
     "payloadDigest"
    ],
    "properties": {
     "schemaDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
       "representation": "raw-artifact",
       "artifact": "the exact complete registered parameter schema document bytes"
      }
     },
     "payloadDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
      "x-opensip-digest": {
       "representation": "canonical-record",
       "record": {
        "payloadClass": "parameter",
        "keyedBy": [
         "schemaDigest"
        ],
        "schemaDigestField": "schemaDigest"
       }
      }
     }
    }
   },
   "x-opensip-order": "canonical-set",
   "description": "every row must also be a row of the Plan analysis-spec parameters: a stage takes no hidden input"
  },
  "outputDomains": {
   "type": "array",
   "maxItems": 128,
   "uniqueItems": true,
   "items": {
    "$ref": "#/$defs/Text"
   },
   "x-opensip-order": "canonical-set"
  },
  "outputSchemaDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])",
   "x-opensip-digest": {
    "representation": "raw-artifact",
    "artifact": "the exact complete registered stage output schema document bytes"
   }
  }
 }
}
